-- Generated by setup/build_load_sql.py. Typed table built from the raw one.
-- Empty strings become NULL; numbers lose commas/$; values like '120 +' become 120
-- with a <column>_capped flag so you know they were capped.
DROP TABLE IF EXISTS sparcs.discharges;
CREATE TABLE sparcs.discharges AS
SELECT
    NULLIF(TRIM(hospital_service_area), '') AS hospital_service_area,
    NULLIF(TRIM(hospital_county), '') AS hospital_county,
    NULLIF(TRIM(operating_certificate_number), '') AS operating_certificate_number,
    NULLIF(TRIM(permanent_facility_id), '') AS permanent_facility_id,
    NULLIF(TRIM(facility_name), '') AS facility_name,
    NULLIF(TRIM(age_group), '') AS age_group,
