    NULLIF(TRIM(gender), '') AS gender,
    NULLIF(TRIM(race), '') AS race,
    NULLIF(TRIM(ethnicity), '') AS ethnicity,
    NULLIF(regexp_replace(length_of_stay, '[,$ +]', '', 'g'), '')::integer AS length_of_stay,
    (length_of_stay LIKE '%+%') AS length_of_stay_capped,
    NULLIF(TRIM(type_of_admission), '') AS type_of_admission,
    NULLIF(TRIM(patient_disposition), '') AS patient_disposition,
    NULLIF(regexp_replace(discharge_year, '[,$ +]', '', 'g'), '')::integer AS discharge_year,
    NULLIF(TRIM(ccsr_diagnosis_code), '') AS ccsr_diagnosis_code,
    NULLIF(TRIM(ccsr_diagnosis_description), '') AS ccsr_diagnosis_description,
    NULLIF(TRIM(ccsr_procedure_code), '') AS ccsr_procedure_code,
    NULLIF(TRIM(ccsr_procedure_description), '') AS ccsr_procedure_description,
    NULLIF(TRIM(apr_drg_code), '') AS apr_drg_code,
    NULLIF(TRIM(apr_drg_description), '') AS apr_drg_description,
    NULLIF(TRIM(apr_mdc_code), '') AS apr_mdc_code,
    NULLIF(TRIM(apr_mdc_description), '') AS apr_mdc_description,
    NULLIF(TRIM(apr_severity_of_illness_code), '') AS apr_severity_of_illness_code,
    NULLIF(TRIM(apr_severity_of_illness_description), '') AS apr_severity_of_illness_description,
    NULLIF(TRIM(apr_risk_of_mortality), '') AS apr_risk_of_mortality,
    NULLIF(TRIM(apr_medical_surgical_description), '') AS apr_medical_surgical_description,
    NULLIF(TRIM(payment_typology_1), '') AS payment_typology_1,
    NULLIF(TRIM(payment_typology_2), '') AS payment_typology_2,
    NULLIF(TRIM(payment_typology_3), '') AS payment_typology_3,
    NULLIF(TRIM(birth_weight), '') AS birth_weight,
    NULLIF(TRIM(emergency_department_indicator), '') AS emergency_department_indicator,
    NULLIF(regexp_replace(total_charges, '[,$ +]', '', 'g'), '')::numeric AS total_charges,
